import{COAST as r}from'./registration.mjs';import{dataRecord,footPair,inCoastContact}from'./support.mjs';
const owners=new WeakMap(),grants=new WeakMap();
function equalData(a,b){if(a===b)return true;if(!a||!b||typeof a!=='object'||typeof b!=='object'||Object.getPrototypeOf(a)!==Object.getPrototypeOf(b))return false;const ak=Reflect.ownKeys(a),bk=Reflect.ownKeys(b);if(ak.length!==bk.length||ak.some(k=>!bk.includes(k)))return false;return ak.every(k=>{const x=Object.getOwnPropertyDescriptor(a,k),y=Object.getOwnPropertyDescriptor(b,k);return Object.hasOwn(x,'value')&&Object.hasOwn(y,'value')&&x.enumerable===y.enumerable&&equalData(x.value,y.value)})}
export function matchesCoastSourceRow(world,id){const p=r.points.find(p=>p.pointId===id);return!!p&&equalData(world?.definition?.points?.[id],p.sourceRow)}
export function createCoastAuthority({getWorld,readNative,getSignal,isPresented}={}){if([getWorld,readNative,getSignal,isPresented].some(f=>typeof f!=='function'))throw Error('COAST_LIVE_OWNER_REQUIRED');const a=Object.freeze({});owners.set(a,{getWorld,readNative,getSignal,isPresented});return a}
export const isCoastAuthority=a=>owners.has(a);
function read(o,p){const n=dataRecord(o.readNative(),['version','sceneId','mapId','revision','imageSHA','maskSHA','foot','facing','state','phase','sessionEpoch','gameplayRevision']);if(!n||n.version!==1||n.sceneId!==r.sceneId||n.mapId!==r.mapId||n.revision!==r.revision||n.imageSHA!==r.image.sha256||n.maskSHA!==r.support.sha256||n.state!==0||n.phase!=='field'||n.gameplayRevision!==r.gameplayRevision||!Number.isSafeInteger(n.sessionEpoch)||n.sessionEpoch<1||!footPair(n.foot)||!inCoastContact(p,n.foot,n.facing)||o.isPresented(n)!==true)return null;return{epoch:n.sessionEpoch,x:n.foot[0],y:n.foot[1],facing:n.facing}}
function canonical(w,p){const s=w.snapshot();return s.position.scene===r.mapId&&s.world.mapId===r.mapId&&matchesCoastSourceRow(w,p.pointId)}
export function mintCoastGrant(a,w,id){const o=owners.get(a),p=r.points.find(p=>p.pointId===id);if(!o||o.getWorld()!==w||!p||!canonical(w,p))throw Error('COAST_UNAVAILABLE');const n=read(o,p),signal=o.getSignal();if(!n)throw Error('COAST_APPROACH_REQUIRED');if(!(signal instanceof AbortSignal)||signal.aborted)throw Error('COAST_LIFECYCLE_REQUIRED');const g=Object.freeze({});grants.set(g,{a,w,p,n,signal});return g}
export function validateCoastGrant(g,w,id){try{const q=grants.get(g),o=q&&owners.get(q.a);if(!q||q.w!==w||!o||o.getWorld()!==w||q.signal.aborted||o.getSignal()!==q.signal||id!==undefined&&id!==q.p.pointId||!canonical(w,q.p))return false;const n=read(o,q.p);return!!n&&n.epoch===q.n.epoch&&n.x===q.n.x&&n.y===q.n.y&&n.facing===q.n.facing}catch{return false}}
export function assertCoastGrant(g,w){if(!validateCoastGrant(g,w))throw Error('COAST_OWNER_DRIFT')}
export const revokeCoastGrant=g=>grants.delete(g);
export function signalCoastGrant(g,w){assertCoastGrant(g,w);return grants.get(g).signal}
export function isCoastRequest(id,request){const p=r.points.find(p=>p.pointId===id);if(!p)return false;const q=dataRecord(request,p.kind==='fishing'?['type','rod']:['type']);return!!q&&q.type===p.kind&&(p.kind!=='fishing'||p.sourceRow.rods.includes(q.rod))}
